<section class="phead"><div class="wrap"><?= crumbs([['Demande de devis', '']]) ?><h1>Demande de devis gratuit</h1><p>Décrivez votre projet, joignez vos fichiers : notre équipe vous répond rapidement avec un prix précis. Sans engagement.</p></div></section>
<form method="post" action="/devis" enctype="multipart/form-data" class="wrap two"><?= csrf_field() ?><input type="hidden" name="ts" value="<?= (int) (microtime(true) * 1000) ?>"><div class="hp" aria-hidden="true"><input name="website" tabindex="-1" autocomplete="off"></div>
<div>
  <?php if ($items): ?><div class="panel"><h2>Produits configurés</h2><?php foreach ($items as $i => $it): ?>
    <div class="cart-line" style="grid-template-columns:1fr auto;margin-bottom:10px"><div><h3><?= e($it['name']) ?> <span class="muted" style="font-size:14px">× <?= (int) $it['qty'] ?></span></h3><ul><?php foreach ($it['summary'] as [$l, $v]): ?><li><b><?= e($l) ?> :</b> <?= e($v) ?></li><?php endforeach; ?></ul></div>
      <div><strong style="color:var(--p)">≈ <?= money($it['est']) ?></strong><br><button class="btn btn-d btn-sm" type="submit" formaction="/devis/retirer" formmethod="post" name="i" value="<?= $i ?>" formnovalidate>Retirer</button></div></div><?php endforeach; ?><small class="muted">Prix indicatif calculé en ligne : le devis définitif tient compte de votre projet exact.</small></div><?php endif; ?>
  <div class="panel"><h2><?= $items ? 'Autre besoin (facultatif)' : 'Votre projet' ?></h2>
    <?php if (feature('quotes.adaptive')): ?><div class="field"><label for="svc">Type de prestation</label><select id="svc" name="service_type"><option value="">— Choisir —</option><?php foreach (quote_services() as $k => $sv): ?><option value="<?= e($k) ?>"><?= e($sv['label']) ?></option><?php endforeach; ?></select><small>Selon votre choix, des précisions techniques vous sont demandées pour un devis plus juste.</small></div>
    <?php foreach (quote_services() as $k => $sv): if (!$sv['fields']) continue; ?><fieldset class="svc-fields" data-service="<?= e($k) ?>" style="border:1px solid var(--line);border-radius:10px;padding:12px 14px;margin:0 0 14px"><legend style="padding:0 6px;font-weight:600"><?= e($sv['label']) ?></legend><div class="row2">
      <?php foreach ($sv['fields'] as $f): $id = 'd_' . $k . '_' . $f['k']; ?><div class="field"><label for="<?= e($id) ?>"><?= e($f['l']) ?></label>
        <?php if ($f['t'] === 'select'): ?><select id="<?= e($id) ?>" name="d_<?= e($f['k']) ?>" data-svc-field="<?= e($k) ?>"><option value="">—</option><?php foreach ($f['opts'] as $ov => $ol): ?><option value="<?= e($ov) ?>"><?= e($ol) ?></option><?php endforeach; ?></select>
        <?php elseif ($f['t'] === 'number'): ?><input id="<?= e($id) ?>" type="number" inputmode="decimal" step="any" min="<?= (int) $f['min'] ?>" max="<?= (int) $f['max'] ?>" name="d_<?= e($f['k']) ?>" data-svc-field="<?= e($k) ?>">
        <?php else: ?><input id="<?= e($id) ?>" name="d_<?= e($f['k']) ?>" maxlength="<?= (int) $f['max'] ?>" data-svc-field="<?= e($k) ?>"><?php endif; ?></div><?php endforeach; ?></div></fieldset><?php endforeach; ?><?php endif; ?>
    <div class="row2"><div class="field"><label for="fp">Produit <span class="opt-t">(facultatif)</span></label><select id="fp" name="free_product"><option value="">— Choisir ou décrire ci-dessous —</option><?php foreach ($prods as $p): ?><option<?= get('produit') === $p['name'] ? ' selected' : '' ?>><?= e($p['name']) ?></option><?php endforeach; ?><option>Autre produit (voir description)</option></select></div><div class="field"><label for="fq">Quantité souhaitée</label><input id="fq" type="number" min="1" name="free_qty" value="1"></div></div>
    <div class="field"><label for="msg">Description du projet</label><textarea id="msg" name="message" rows="5" maxlength="3000" placeholder="Dimensions, quantités, couleurs, finitions, délai souhaité, lieu de livraison…"></textarea></div>
    <?php if (feature('quotes.adaptive')): ?><div class="field"><label for="dd">Date souhaitée <span class="opt-t">(facultatif)</span></label><input id="dd" type="date" name="desired_date" min="<?= date('Y-m-d') ?>" max="<?= date('Y-m-d', strtotime('+730 days')) ?>"><small>Indicative : nous confirmons les délais réels dans le devis.</small></div><?php endif; ?>
    <?php if (feature('files')): ?><div class="field"><label for="fl">Fichiers <span class="opt-t">(facultatif · <?= e(strtoupper(implode(', ', Files::allowed()))) ?> · <?= (int) Settings::get('upload_max_mb', 50) ?> Mo max)</span></label><input id="fl" type="file" name="files[]" multiple></div><?php endif; ?></div>
  <div class="panel"><h2>Vos coordonnées</h2>
    <div class="row2"><div class="field"><label for="n">Nom complet *</label><input id="n" name="name" required value="<?= e($u['name'] ?? '') ?>" autocomplete="name"></div><div class="field"><label for="c">Entreprise</label><input id="c" name="company" value="<?= e($u['company'] ?? '') ?>"></div></div>
    <div class="row2"><div class="field"><label for="p">Téléphone / WhatsApp</label><input id="p" type="tel" name="phone" value="<?= e($u['phone'] ?? '') ?>" placeholder="+225 07 00 00 00 00"></div><div class="field"><label for="e">E-mail</label><input id="e" type="email" name="email" value="<?= e($u['email'] ?? '') ?>"></div></div>
    <small class="muted">Indiquez au moins un téléphone ou un e-mail. Vos données ne sont utilisées que pour répondre à votre demande.</small><div class="mt"><button class="btn btn-a btn-lg" type="submit"><?= ic('send') ?? '' ?> Envoyer ma demande</button></div></div>
</div>
<aside class="summary"><h3>Comment ça marche ?</h3><div class="sl"><span>1. Vous décrivez votre projet</span></div><div class="sl"><span>2. Nous vous envoyons un devis chiffré en FCFA</span></div><div class="sl"><span>3. Vous acceptez en ligne</span></div><div class="sl"><span>4. Production, livraison, suivi</span></div>
